type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    // We expect `shape` to have exactly two elements: [R, C]
    assert!(
        shape.len() == 2,
        "Shape must contain exactly two dimensions"
    );
    let rows = shape[0] as usize;
    let cols = shape[1] as usize;

    // One of the dimensions must match the length of `a`.
    if a.len() == rows {
        // Treat `a` as a column vector: broadcast each element across `cols`
        let mut result = Vec::with_capacity(rows);
        for &val in &a {
            result.push(vec![val; cols]);
        }
        result
    } else if a.len() == cols {
        // Treat `a` as a row vector: replicate the entire row `rows` times
        let mut result = Vec::with_capacity(rows);
        for _ in 0..rows {
            result.push(a.clone());
        }
        result
    } else {
        panic!(
            "Length of input ({}) does not match any dimension of the shape {:?}",
            a.len(),
            shape
        );
    }
}